import { MakeLogicType, actions, kea, path, reducers } from 'kea'
import { actionToUrl, router, urlToAction } from 'kea-router'

import { Breadcrumb } from '~/types'

export const SOURCES_SCENE_TABS = ['sources', 'alerts'] as const
export type SourcesSceneTab = (typeof SOURCES_SCENE_TABS)[number]

const DEFAULT_TAB: SourcesSceneTab = 'sources'

const isSourcesSceneTab = (value: unknown): value is SourcesSceneTab =>
    SOURCES_SCENE_TABS.includes(value as SourcesSceneTab)

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourcesSceneLogicValues {
    activeTab: SourcesSceneTab
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourcesSceneLogicActions {
    setActiveTab: (activeTab: SourcesSceneTab) => {
        activeTab: 'alerts' | 'sources'
    }
}

export type sourcesSceneLogicType = MakeLogicType<sourcesSceneLogicValues, sourcesSceneLogicActions>

export const sourcesSceneLogic = kea<sourcesSceneLogicType>([
    path(['products', 'dataWarehouse', 'sourcesSceneLogic']),
    actions({
        setActiveTab: (activeTab: SourcesSceneTab) => ({ activeTab }),
    }),
    reducers({
        activeTab: [
            DEFAULT_TAB as SourcesSceneTab,
            {
                setActiveTab: (_, { activeTab }) => activeTab,
            },
        ],
    }),
    () => ({
        selectors: {
            breadcrumbs: [
                () => [],
                (): Breadcrumb[] => {
                    return [
                        {
                            key: 'Sources',
                            name: 'Sources',
                            iconType: 'data_pipeline',
                        },
                    ]
                },
            ],
        },
    }),
    actionToUrl(({ values }) => ({
        setActiveTab: () => {
            const { searchParams, hashParams } = router.values
            const { tab: _tab, ...rest } = searchParams
            const params = values.activeTab === DEFAULT_TAB ? rest : { ...rest, tab: values.activeTab }
            return [router.values.location.pathname, params, hashParams]
        },
    })),
    urlToAction(({ actions, values }) => ({
        '/data-management/sources': (_, { tab }) => {
            const nextTab = isSourcesSceneTab(tab) ? tab : DEFAULT_TAB
            if (nextTab !== values.activeTab) {
                actions.setActiveTab(nextTab)
            }
        },
    })),
])
